645	  const labelElements = Array.from(root.querySelectorAll('label, [id]')).filter((candidate) => ownLabelText(candidate) === labelText);
646	  for (const labelElement of labelElements) {
647	    const nested = labelElement.querySelector('select');
648	    if (nested) {
649	      return nested;
650	    }
651	    const targetId = labelElement.getAttribute('for');
652	    const byFor = targetId ? root.querySelector(`select#${CSS.escape(targetId)}`) : null;
653	    if (byFor instanceof HTMLSelectElement) {
654	      return byFor;
