780	export class FakeActivityHealthApi extends ActivityHealthApi {
781	  readonly requests: ActivityHealthRequest[] = [];
782	  private readonly reportsByKey = new Map<string, ActivityHealthReport>();
783	  private readonly queuedFailures: HttpErrorResponse[] = [];
784	  private readonly heldResponses: { request: ActivityHealthRequest; response: Subject<ActivityHealthReport> }[] = [];
785	  private holdNextResponse = false;
786	
787	  constructor(private readonly accounts: readonly Account[] = seedAccounts()) {
788	    super();
789	    scenarioReports().forEach((report) => this.register(report));
790	  }
791	
792	  register(report: ActivityHealthReport): this {
793	    this.reportsByKey.set(reportKey(report.account.id, report.week.start, report.eventType), report);
794	    return this;
795	  }
796	
797	  failNext(failure: HttpErrorResponse): this {
798	    this.queuedFailures.push(failure);
799	    return this;
800	  }
801	
802	  holdNext(): this {
803	    this.holdNextResponse = true;
804	    return this;
805	  }
806	
807	  releaseHeld(): void {
808	    const held = this.heldResponses.shift();
809	    if (!held) {
810	      throw new Error('No held activity-health request to release');
811	    }
812	    held.response.next(this.resolve(held.request));
813	    held.response.complete();
814	  }
815	
816	  getActivityHealth(request: ActivityHealthRequest): Observable<ActivityHealthReport> {
817	    this.requests.push({ ...request });
818	    const queuedFailure = this.queuedFailures.shift();
819	    if (queuedFailure) {
820	      return afterMicrotask(() => throwError(() => queuedFailure));
821	    }
822	    if (this.holdNextResponse) {
823	      this.holdNextResponse = false;
824	      const response = new Subject<ActivityHealthReport>();
825	      this.heldResponses.push({ request: { ...request }, response });
826	      return response.asObservable();
827	    }
828	    return afterMicrotask(() => {
829	      const rejection = this.rejectionFor(request);
830	      return rejection ? throwError(() => rejection) : of(this.resolve(request));
831	    });
832	  }
833	
834	  private rejectionFor(request: ActivityHealthRequest): HttpErrorResponse | null {
835	    const earliestWeek = EARLIEST_WEEK_BY_ACCOUNT_ID.get(request.accountId);
836	    if (!earliestWeek || !this.accounts.some((account) => account.id === request.accountId)) {
837	      return notFoundProblem();
838	    }
839	    if (!(EVENT_TYPES as readonly string[]).includes(request.eventType)) {
840	      return validationProblem('Type', 'The type field is invalid.');
841	    }
842	    if (request.week === null) {
843	      return null;
844	    }
845	    if (!isMonday(request.week)) {
846	      return validationProblem('Week', 'The week must be a Monday in yyyy-MM-dd format.');
847	    }
848	    if (request.week < earliestWeek || request.week > LATEST_COMPLETE_WEEK) {
849	      return validationProblem('Week', 'The week is outside the available range.');
850	    }
851	    return null;
852	  }
853	
854	  private resolve(request: ActivityHealthRequest): ActivityHealthReport {
855	    const weekStart = request.week ?? LATEST_COMPLETE_WEEK;
856	    const registered = this.reportsByKey.get(reportKey(request.accountId, weekStart, request.eventType));
857	    if (registered) {
858	      return structuredClone(registered);
859	    }
860	    const account = this.accounts.find((candidate) => candidate.id === request.accountId);
861	    if (!account) {
862	      throw new Error(`Fake has no account ${request.accountId}`);
863	    }
864	    return genericReport(account, weekStart, request.eventType);
865	  }
866	}
