      .subscribe({ error: (error: unknown) => (receivedError = error) });
    httpTesting
      .expectOne((candidate) => candidate.urlWithParams.startsWith('/api/accounts/8/activity-health'))
      .flush(problem, { status: 400, statusText: 'Bad Request' });

